/**
 * 资金账本初始化：余额投影段（PFH-05）。
 *
 * 由 provider-finance-activation-projection.ts 按「余额投影」分段下沉而来。
 *
 * 工程约束：余额公式的唯一实现在 provider-finance-balance-components.ts。
 * 本模块只用 `addBalanceComponents` / `balanceFormulaMatches` 组装虚拟事实，
 * **不得**自行书写 `.plus/.minus` 链或冲销正负号。
 */
import {
  type ActivationCurrency,
  type ActivationGap,
  type ProjectedAccountBalance,
} from "./provider-finance-activation.js";
import {
  addBalanceComponents,
  balanceAmount,
  balanceFormulaMatches,
  emptyBalanceComponents,
  isBalanceNegative,
  money,
  Money,
} from "./provider-finance-balance-components.js";
import {
  accountKey,
  compareStrings,
  gap,
  type ActivationProjectionInput,
  type ActivationScopeAccountInput,
} from "./provider-finance-activation-inputs.js";
import type { UsageRepairPlan } from "./provider-finance-activation-draft.js";

/** 用量修复对 `usageDebits` 分量的确定性增量（按账户），符号仍由共享公式决定。 */
export function computeUsageDebitDeltas(
  input: ActivationProjectionInput, plan: UsageRepairPlan,
): Map<string, string> {
  const deltas = new Map<string, string>();
  const add = (key: string, amount: string) => {
    deltas.set(key, money(new Money(deltas.get(key) ?? 0).plus(amount)));
  };
  for (const line of input.ledgerLines) {
    if (line.resourceMode !== "API" || line.apiCost === null) continue;
    const repaired = plan.repairByLine.get(line.id);
    const statusBefore = line.apiCostStatus;
    const currencyBefore = line.apiCostCurrency;
    const statusAfter = repaired?.apiCostStatus ?? statusBefore;
    const currencyAfter = repaired ? repaired.apiCostCurrency : currencyBefore;
    const counted = (status: string | null, currency: ActivationCurrency | null): string | null =>
      status === "PRICED_USAGE" && currency !== null ? line.apiCost : null;
    const before = counted(statusBefore, currencyBefore);
    const after = counted(statusAfter, currencyAfter);
    if (before === after) continue;
    if (before !== null && currencyBefore !== null) {
      add(accountKey(line.resourceId, currencyBefore), new Money(before).negated().toString());
    }
    if (after !== null && currencyAfter !== null) add(accountKey(line.resourceId, currencyAfter), after);
  }
  return deltas;
}

/** 余额投影与守恒（PFH-05，复用共享聚合语义）。 */
export function projectAccountBalances(
  input: ActivationProjectionInput,
  plan: UsageRepairPlan,
  scopeAccounts: Map<string, ActivationScopeAccountInput>,
  gaps: ActivationGap[],
): ProjectedAccountBalance[] {
  const accounts: ProjectedAccountBalance[] = [];
  const virtualOpenings = new Map<string, string>();
  for (const opening of input.draft.apiOpeningBalances) {
    const key = accountKey(opening.resourceId, opening.accountCurrency);
    virtualOpenings.set(key, money(new Money(virtualOpenings.get(key) ?? 0).plus(opening.accountAmount)));
  }
  const virtualRecharges = new Map<string, string>();
  for (const recharge of input.draft.historicalApiRecharges) {
    const key = accountKey(recharge.resourceId, recharge.accountCurrency);
    virtualRecharges.set(key, money(new Money(virtualRecharges.get(key) ?? 0).plus(recharge.accountAmount)));
  }
  const usageDebitDeltas = computeUsageDebitDeltas(input, plan);
  const realComponents = new Map(input.accountComponents.map((row) => [accountKey(row.resourceId, row.currency), row]));
  const accountKeys = [...new Set([...realComponents.keys(), ...scopeAccounts.keys()])].sort(compareStrings);
  for (const key of accountKeys) {
    const account = scopeAccounts.get(key);
    if (!account) continue;
    const [resourceId, currency] = key.split(":") as [string, ActivationCurrency];
    const real = realComponents.get(key);
    const base = real?.components ?? emptyBalanceComponents();
    const components = addBalanceComponents(base, {
      openingBalance: virtualOpenings.get(key) ?? null,
      recharges: virtualRecharges.get(key) ?? null,
      usageDebits: usageDebitDeltas.get(key) ?? null,
    });
    // 非平凡校验：数据库独立算出的余额必须等于用共享公式重算的结果。
    const formulaMatches = real === undefined || real.reportedBalance === null
      ? true
      : balanceFormulaMatches(real.components, real.reportedBalance);
    accounts.push({ resourceId, currency, ...components, balance: balanceAmount(components), formulaMatches });
    // 失败关闭：数据库独立算出的余额必须等于用共享公式重算的结果；不一致即缺口，不得返回 GO_CANDIDATE。
    if (!formulaMatches && real !== undefined && real.reportedBalance !== null) {
      gaps.push(gap("BALANCE_FORMULA_MISMATCH", "BALANCE",
        "账户余额与共享公式重算结果不一致，必须先完成对账",
        {
          resourceId, accountCurrency: currency,
          detail: `重算 ${balanceAmount(real.components)} ≠ 已落库 ${real.reportedBalance}`,
        }));
    }
    if (isBalanceNegative(components)) {
      gaps.push(gap("NEGATIVE_BALANCE", "BALANCE", "投影余额为负，必须先完成对账",
        { resourceId, accountCurrency: currency, detail: balanceAmount(components) }));
    }
  }
  accounts.sort((left, right) => compareStrings(left.resourceId, right.resourceId)
    || compareStrings(left.currency, right.currency));
  return accounts;
}

src/provider-finance-activation-conserva.source:
/**
 * 资金账本初始化：守恒检查段——上海自然月窗口、逐月缺口抵消与归属/分类缺口（PFH-03、PFH-05）。
 *
 * 由 provider-finance-activation-projection.ts 按「守恒检查」分段下沉而来。
 *
 * 工程约束：
 * - 经营账单缺口的权威口径是数据库层 `countFinanceGaps`（SQL 单一来源）。
 *   本模块只对草稿与用量修复带来的**增量**做确定性抵消，不重新定义缺口规则。
 * - 缺口必须结构化且可定位到资源、账户、旧记录、用量行或月份；不得只返回一条错误字符串。
 */
import {
  type ActivationGap,
  type ActivationGapCode,
} from "./provider-finance-activation.js";
import {
  accountKey,
  compareStrings,
  gap,
  hasTokens,
  isWithin,
  ledgerEffectiveAt,
  type ActivationProjectionInput,
} from "./provider-finance-activation-inputs.js";
import type { UsageRepairPlan } from "./provider-finance-activation-draft.js";

// ===== 上海自然月窗口 =====

/** UTC 瞬间所属的上海自然月（YYYY-MM）。 */
export function shanghaiMonthOf(instant: string | Date): string {
  const date = instant instanceof Date ? instant : new Date(instant);
  if (Number.isNaN(date.getTime())) throw new Error("不是合法时间");
  return new Date(date.getTime() + 8 * 3600_000).toISOString().slice(0, 7);
}

/** 上海自然月的 `[start, endExclusive)`。 */
export function shanghaiMonthBounds(month: string): { start: Date; endExclusive: Date } {
  if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) throw new Error(`${month} 不是合法月份`);
  const [year, monthNumber] = month.split("-").map(Number);
  const nextYear = monthNumber === 12 ? year! + 1 : year!;
  const nextMonth = monthNumber === 12 ? 1 : monthNumber! + 1;
  return {
    start: new Date(`${month}-01T00:00:00+08:00`),
    endExclusive: new Date(`${nextYear}-${String(nextMonth).padStart(2, "0")}-01T00:00:00+08:00`),
  };
}

/**
 * 守恒窗口涉及的月份（PFH-05：切换时点至候选水位，覆盖所有涉及月份）。
 * 首月起点不早于切换时点，末月终点不晚于候选水位；
 * 末月被截断时终点取 `snapshot_at + 1ms`，使比较式 `>= start AND < end` 恰好包含该瞬间。
 */
export interface ConservationMonth {
  month: string;
  start: string;
  endExclusive: string;
  /** true 表示该月被候选水位截断（未走完整个自然月）。 */
  clipped: boolean;
}

export function conservationMonths(cutoverIso: string, snapshotAtIso: string): ConservationMonth[] {
  const cutover = new Date(cutoverIso);
  const snapshotAt = new Date(snapshotAtIso);
  if (Number.isNaN(cutover.getTime()) || Number.isNaN(snapshotAt.getTime())) {
    throw new Error("守恒窗口边界不是合法时间");
  }
  if (snapshotAt.getTime() < cutover.getTime()) throw new Error("候选水位不得早于切换时点");
  const firstMonth = shanghaiMonthOf(cutover);
  const lastMonth = shanghaiMonthOf(snapshotAt);
  const months: ConservationMonth[] = [];
  let cursor = firstMonth;
  // 月份单调递增；计数上限避免非法输入造成死循环。
  for (let guard = 0; guard < 1200; guard += 1) {
    const bounds = shanghaiMonthBounds(cursor);
    const start = bounds.start.getTime() < cutover.getTime() ? cutover : bounds.start;
    const monthEnd = bounds.endExclusive;
    const clipped = monthEnd.getTime() > snapshotAt.getTime();
    months.push({
      month: cursor,
      start: start.toISOString(),
      endExclusive: (clipped ? new Date(snapshotAt.getTime() + 1) : monthEnd).toISOString(),
      clipped,
    });
    if (cursor === lastMonth) break;
    const [year, monthNumber] = cursor.split("-").map(Number);
    cursor = monthNumber === 12 ? `${year! + 1}-01` : `${year}-${String(monthNumber! + 1).padStart(2, "0")}`;
  }
  return months;
}

// ===== 经营账单缺口的草稿增量抵消 =====

const MONTHLY_GAP_CODES = [
  "API_USAGE_COST_UNKNOWN", "API_COST_CURRENCY_MISSING", "API_COST_CURRENCY_CONFLICT",
  "OPENING_BALANCE_MISSING", "SUBSCRIPTION_PERIOD_MISSING", "CASH_PAID_CNY_MISSING",
] as const;

export function mapMonthlyGapCode(code: string): ActivationGapCode {
  switch (code) {
    case "API_USAGE_COST_UNKNOWN": return "UNKNOWN_COST";
    case "API_COST_CURRENCY_MISSING": return "MISSING_API_CURRENCY";
    case "API_COST_CURRENCY_CONFLICT": return "CONFLICTING_API_CURRENCY";
    case "OPENING_BALANCE_MISSING": return "MISSING_OPENING_BALANCE";
    case "SUBSCRIPTION_PERIOD_MISSING": return "UNATTRIBUTED_PLAN_USAGE";
    case "CASH_PAID_CNY_MISSING": return "MISSING_RECHARGE_CASH_PAID";
    default: return "INCOMPLETE_OPERATING_BILL";
  }
}

/**
 * 逐月缺口 = 权威 SQL 口径的真实缺口 − 草稿与修复带来的抵消数。
 *
 * 只做计数抵消，不重新定义缺口规则；抵消数必须可追溯到具体草稿行或具体用量行。
 * 抵消数被 `Math.min` 限制在真实计数以内，因此**只可能减少已知缺口，不可能掩盖真实缺口**。
 */
export function computeMonthlyGapDeltas(
  input: ActivationProjectionInput,
  plan: UsageRepairPlan,
  draftOpeningKeys: ReadonlySet<string>,
  window: readonly ConservationMonth[],
): Array<{ month: string; gaps: string[] }> {
  const realByMonth = new Map(input.monthlyGaps.map((entry) => [entry.month, entry.gaps]));
  return window.map((entry) => {
    const real = new Map((realByMonth.get(entry.month) ?? []).map((row) => [row.code, row.count]));
    const closed = new Map<string, number>(MONTHLY_GAP_CODES.map((code) => [code, 0]));

    let unknownClosed = 0;
    let currencyMissingClosed = 0;
    let currencyConflictClosed = 0;
    let periodMissingClosed = 0;
    const pricedAccountsInMonth = new Set<string>();
    for (const line of input.ledgerLines) {
      if (!isWithin(ledgerEffectiveAt(line), entry.start, entry.endExclusive)) continue;
      const repaired = plan.repairByLine.get(line.id);
      if (repaired) {
        if (line.apiCostStatus === null && repaired.apiCostStatus === "PRICED_USAGE") unknownClosed += 1;
        if (line.apiCostCurrency === null && repaired.apiCostCurrency !== null) currencyMissingClosed += 1;
        if (line.apiCostCurrency !== null && repaired.apiCostCurrency !== null
          && repaired.apiCostCurrency === line.billingRuleSnapshotCurrency) currencyConflictClosed += 1;
        if (line.subscriptionPeriodId === null && repaired.subscriptionPeriodId !== null) periodMissingClosed += 1;
      }
      if (line.resourceMode !== "API" || !line.operatingConsumption) continue;
      const status = repaired?.apiCostStatus ?? line.apiCostStatus;
      const currency = repaired ? repaired.apiCostCurrency : line.apiCostCurrency;
      if (status === "PRICED_USAGE" && currency !== null) {
        pricedAccountsInMonth.add(accountKey(line.resourceId, currency));
      }
    }
    closed.set("API_USAGE_COST_UNKNOWN", unknownClosed);
    closed.set("API_COST_CURRENCY_MISSING", currencyMissingClosed);
    closed.set("API_COST_CURRENCY_CONFLICT", currencyConflictClosed);
    closed.set("SUBSCRIPTION_PERIOD_MISSING", periodMissingClosed);
    // 只有草稿新补的账户才能抵消该月缺口；已有事实造成的缺口由权威 SQL 计数负责，不得再次抵扣。
    closed.set("OPENING_BALANCE_MISSING",
      [...draftOpeningKeys].filter((key) => pricedAccountsInMonth.has(key)).length);
    closed.set("CASH_PAID_CNY_MISSING",
      [...input.draft.historicalApiRecharges.map((row) => row.occurredAt),
        ...input.draft.codingPlanPurchases.map((row) => row.occurredAt)]
        .filter((occurredAt) => isWithin(occurredAt, entry.start, entry.endExclusive)).length);

    const remaining = MONTHLY_GAP_CODES.filter((code) => {
      const count = real.get(code) ?? 0;
      if (count <= 0) return false;
      return count - Math.min(count, closed.get(code) ?? 0) > 0;
    });
    return { month: entry.month, gaps: [...remaining] };
  });
}

/** Coding Plan 用量唯一归属（PFH-03）。 */
export function collectPlanAttributionGaps(plan: UsageRepairPlan, gaps: ActivationGap[]): void {
  for (const ambiguous of plan.ambiguousPeriodLines) {
    gaps.push(gap("OVERLAPPING_PERIOD", "PERIOD",
      "同一套餐用量被多个未冲销周期覆盖，无法唯一归属", {
        resourceId: ambiguous.line.resourceId, ledgerLineId: ambiguous.line.id,
        detail: ambiguous.periodIds.join(","),
      }));
  }
  for (const line of plan.unattributedPlanLines) {
    gaps.push(gap("UNATTRIBUTED_PLAN_USAGE", "USAGE",
      "套餐用量没有任何覆盖周期，无法唯一归属", {
        resourceId: line.resourceId, ledgerLineId: line.id,
        month: shanghaiMonthOf(ledgerEffectiveAt(line)),
      }));
  }
}

/** 用量费用分类与 Token 守恒（失败关闭 #4、#6）；返回 Token 是否守恒。 */
export function collectUsageClassificationGaps(
  input: ActivationProjectionInput, plan: UsageRepairPlan, gaps: ActivationGap[],
): boolean {
  let tokenConserved = true;
  const usageEventById = new Map(input.usageEvents.map((usage) => [usage.id, usage]));
  for (const line of [...input.ledgerLines].sort((left, right) => compareStrings(left.id, right.id))) {
    const repaired = plan.repairByLine.get(line.id);
    const statusAfter = repaired?.apiCostStatus ?? line.apiCostStatus;
    const currencyAfter = repaired ? repaired.apiCostCurrency : line.apiCostCurrency;
    if (line.resourceMode === "API") {
      if ((statusAfter === null || statusAfter === "UNKNOWN_COST") && hasTokens(line)
        && !line.legacyCostResolved) {
        gaps.push(gap("UNKNOWN_COST", "USAGE", "API 用量费用状态未明确（UNKNOWN_COST）", {
          resourceId: line.resourceId, ledgerLineId: line.id,
          month: shanghaiMonthOf(ledgerEffectiveAt(line)),
        }));
      }
      if (line.apiCost !== null && currencyAfter === null
        && statusAfter !== "CONFIRMED_ZERO_NO_UPSTREAM") {
        gaps.push(gap("MISSING_API_CURRENCY", "USAGE", "已定价 API 用量缺少结算币种",
          { resourceId: line.resourceId, ledgerLineId: line.id }));
      }
      if (currencyAfter !== null && line.billingRuleSnapshotCurrency !== null
        && currencyAfter !== line.billingRuleSnapshotCurrency) {
        gaps.push(gap("CONFLICTING_API_CURRENCY", "USAGE", "结算币种与计价规则快照币种冲突", {
          resourceId: line.resourceId, ledgerLineId: line.id,
          detail: `${currencyAfter} vs ${line.billingRuleSnapshotCurrency}`,
        }));
      }
      if ((repaired?.settledAt ?? line.settledAt) === null) {
        gaps.push(gap("MISSING_SETTLEMENT_TIME", "USAGE", "用量缺少结算时间",
          { resourceId: line.resourceId, ledgerLineId: line.id }));
      }
    }
    const usage = usageEventById.get(line.usageEventId);
    const tokensMatch = usage !== undefined
      && usage.inputTokens === line.rawInputTokens
      && usage.outputTokens === line.rawOutputTokens
      && usage.cacheTokens === line.rawCacheTokens
      && usage.reasoningTokens === line.rawReasoningTokens;
    if (!tokensMatch) {
      tokenConserved = false;
      gaps.push(gap("TOKEN_CONSERVATION_MISMATCH", "TOKEN", "Usage 与 Ledger Token 不守恒",
        { resourceId: line.resourceId, ledgerLineId: line.id }));
    }
  }
  return tokenConserved;
}

mutants.replacement:
[...repairByLine.values()].map((target): UsageRepairBaselineRow => ({
  ledgerLineId: target.ledgerLineId,
  eligibleRepairs: eligibleFieldsFor(input.ledgerLines.find(row => row.id === target.ledgerLineId)!, target),
  ...usageRepairFieldDigests(input.ledgerLines.find(row => row.id === target.ledgerLineId)!)
}))

src/provider-finance-activation-draft.ts.source:
/**
 * 资金账本初始化：草稿规范化段——虚拟周期展开与用量修复计划（PFH-03、PFH-04）。
 *
 * 由 provider-finance-activation-projection.ts 按「草稿规范化」分段下沉而来。
 * 计划（v1.2 §4.5）要求预检与激活复用同一套修复计划与字段基准，
 * 因此本模块只做纯计算：无数据库访问、无时钟读取、无随机数。
 */
import {
  USAGE_REPAIR_FIELDS,
  hashStable,
  type NormalizedActivationCandidate,
  type UsageRepairBaselineRow,
  type UsageRepairField,
} from "./provider-finance-activation.js";
import {
  compareStrings,
  hasTokens,
  instantOf,
  ledgerEffectiveAt,
  type LedgerLineFactRow,
  type UsageRepairTarget,
} from "./provider-finance-activation-inputs.js";

// ===== 历史修复字段基准（PFH-04） =====

const TARGET_FIELD_PROPERTIES = ["settledAt", "apiCostCurrency", "apiCostStatus", "subscriptionPeriodId"] as const;

/**
 * 逐行目标/非目标字段基准摘要。
 *
 * 目标字段固定为 `USAGE_REPAIR_FIELDS` 的四个，其余字段全部属于非目标集合。
 * 摘要使用领域层稳定哈希（键排序、null 归一），与既有回填
 * （`provider-finance-usage-backfill.ts` 的 `to_jsonb(line) - <四列>`）语义一致：
 * 逐行比对的门槛都是「非目标字段一个都不能变」。
 *
 * 预检与激活必须调用**同一个**本函数；激活侧从数据库行重建同一 `LedgerLineFactRow` 形状。
 */
export function usageRepairFieldDigests(line: LedgerLineFactRow): {
  targetFieldsBeforeHash: string;
  nonTargetFieldsBeforeHash: string;
} {
  const target = new Map<string, unknown>([
    ["settled_at", line.settledAt],
    ["api_cost_currency", line.apiCostCurrency],
    ["api_cost_status", line.apiCostStatus],
    ["subscription_period_id", line.subscriptionPeriodId],
  ]);
  const targetFieldsBeforeHash = hashStable([...target.entries()]);
  const nonTargetFieldsBeforeHash = hashStable(
    Object.entries(line)
      .filter(([key]) => !(TARGET_FIELD_PROPERTIES as readonly string[]).includes(key))
      .sort(([left], [right]) => compareStrings(left, right)),
  );
  return { targetFieldsBeforeHash, nonTargetFieldsBeforeHash };
}

export function eligibleFieldsFor(line: LedgerLineFactRow, target: UsageRepairTarget): UsageRepairField[] {
  const fields: UsageRepairField[] = [];
  if (line.settledAt === null && target.settledAt !== null) fields.push("settled_at");
  if (line.apiCostCurrency === null && target.apiCostCurrency !== null) fields.push("api_cost_currency");
  if (line.apiCostStatus === null && target.apiCostStatus !== null) fields.push("api_cost_status");
  if (line.subscriptionPeriodId === null && target.subscriptionPeriodId !== null) {
    fields.push("subscription_period_id");
  }
  return fields.filter((field) => (USAGE_REPAIR_FIELDS as readonly string[]).includes(field));
}

// ===== 用量修复计划 =====

export interface UsageRepairPlan {
  baseline: UsageRepairBaselineRow[];
  targets: UsageRepairTarget[];
  repairByLine: Map<string, UsageRepairTarget>;
  /** 因周期歧义而无法唯一归属的行（NO_GO）。 */
  ambiguousPeriodLines: Array<{ line: LedgerLineFactRow; periodIds: string[] }>;
  /** 覆盖周期数为 0 且尚无归属的套餐用量行。 */
  unattributedPlanLines: LedgerLineFactRow[];
}

export interface PeriodCandidate {
  id: string;
  resourceId: string;
  periodStart: string;
  periodEndExclusive: string;
  reversed: boolean;
}

/** 覆盖某用量行的未冲销周期（按 id 稳定排序；多于一个即歧义，不得任意选择）。 */
export function coveringPeriods(
  line: LedgerLineFactRow, periods: readonly PeriodCandidate[],
): PeriodCandidate[] {
  const at = instantOf(ledgerEffectiveAt(line));
  return periods
    .filter((period) => period.resourceId === line.resourceId
      && !period.reversed
      && instantOf(period.periodStart) <= at
      && instantOf(period.periodEndExclusive) > at)
    .sort((left, right) => compareStrings(left.id, right.id));
}

/**
 * 把草稿购买/跨切换周期展开为虚拟周期。
 * 激活会在同一事务内先写入这些周期，再执行用量修复，因此
 * `subscription_period_id` 的修复目标允许指向 `draft:<key>`，由激活侧解析为真实 id。
 */
export function virtualPeriodsOf(candidate: NormalizedActivationCandidate): Array<PeriodCandidate & { key: string }> {
  const periods: Array<PeriodCandidate & { key: string }> = [];
  for (const purchase of candidate.codingPlanPurchases) {
    periods.push({
      id: `draft:${purchase.recordIdempotencyKey}`,
      key: purchase.recordIdempotencyKey,
      resourceId: purchase.resourceId,
      periodStart: purchase.periodStart,
      periodEndExclusive: purchase.periodEndExclusive,
      reversed: false,
    });
  }
  for (const carryover of candidate.codingPlanCarryovers) {
    periods.push({
      id: `draft:${carryover.snapshotId}`,
      key: carryover.snapshotId,
      resourceId: carryover.resourceId,
      periodStart: carryover.periodStart,
      periodEndExclusive: carryover.periodEndExclusive,
      reversed: false,
    });
  }
  return periods;
}

export function planUsageRepairs(input: {
  ledgerLines: readonly LedgerLineFactRow[];
  periods: readonly PeriodCandidate[];
}): UsageRepairPlan {
  const repairByLine = new Map<string, UsageRepairTarget>();
  const ambiguousPeriodLines: Array<{ line: LedgerLineFactRow; periodIds: string[] }> = [];
  const unattributedPlanLines: LedgerLineFactRow[] = [];

  for (const line of input.ledgerLines) {
    const target: UsageRepairTarget = {
      ledgerLineId: line.id,
      settledAt: line.settledAt,
      apiCostCurrency: line.apiCostCurrency,
      apiCostStatus: line.apiCostStatus,
      subscriptionPeriodId: line.subscriptionPeriodId,
    };
    let touched = false;
    if (line.settledAt === null) {
      target.settledAt = line.createdAt;
      touched = true;
    }
    if (line.resourceMode === "API" && line.apiCostStatus === null) {
      const snapshotCurrency = line.billingRuleSnapshotCurrency;
      if (line.apiCost !== null && (snapshotCurrency === "CNY" || snapshotCurrency === "USD")
        && (line.apiCostCurrency === null || line.apiCostCurrency === snapshotCurrency)) {
        target.apiCostCurrency = snapshotCurrency;
        target.apiCostStatus = "PRICED_USAGE";
        touched = true;
      } else if (line.zeroConfirmedEligible && Number(line.apiCost ?? "0") === 0
        && line.apiCostCurrency === null && line.billingRuleId === null && !hasTokens(line)) {
        target.apiCostStatus = "CONFIRMED_ZERO_NO_UPSTREAM";
        touched = true;
      } else if (line.apiCost === null && line.apiCostCurrency === null) {
        target.apiCostStatus = "UNKNOWN_COST";
        touched = true;
      }
    }
    if (line.resourceMode === "CODING_PLAN" && line.apiCostStatus === null
      && line.apiCost === null && line.apiCostCurrency === null) {
      target.apiCostStatus = "NOT_APPLICABLE";
      touched = true;
    }
    if (line.resourceMode === "CODING_PLAN" && line.subscriptionPeriodId === null) {
      const covering = coveringPeriods(line, input.periods);
      if (covering.length > 1) {
        ambiguousPeriodLines.push({ line, periodIds: covering.map((period) => period.id) });
      } else if (covering.length === 1) {
        target.subscriptionPeriodId = covering[0]!.id;
        touched = true;
      } else {
        unattributedPlanLines.push(line);
      }
    }
    if (touched) repairByLine.set(line.id, target);
  }

  const baseline = [...repairByLine.values()]
    .map((target): UsageRepairBaselineRow => ({
      ledgerLineId: target.ledgerLineId,
      eligibleRepairs: eligibleFieldsFor(
        input.ledgerLines.find((row) => row.id === target.ledgerLineId)!, target),
      ...usageRepairFieldDigests(
        input.ledgerLines.find((row) => row.id === target.ledgerLineId)!),
    }))
    .sort((left, right) => compareStrings(left.ledgerLineId, right.ledgerLineId));

  return {
    baseline,
    targets: [...repairByLine.values()].sort((left, right) => compareStrings(left.ledgerLineId, right.ledgerLineId)),
    repairByLine,
    ambiguousPeriodLines,
    unattributedPlanLines,
  };
}

